import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createNode as _placeholder } from '@/primitives';
import { createText as _textPlaceholder } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---------- Plane ----------
  const planeGeom = new PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial();
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture (if provided)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ---------- Text ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color:
        item.role === 'headline'
          ? config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2'
          : config.intent?.visualSpec?.colors?.ink ?? '#16161d',
      align: 'center',
    });
    // Position text slightly above the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveCleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && prim.name && typeof ctx.primitives[prim.name] === 'function') {
        const { cleanup } = ctx.primitives[prim.name](root, prim.params);
        if (typeof cleanup === 'function') primitiveCleanups.push(cleanup);
      }
    }
  }

  // ---------- Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose plane geometry & material
    planeGeom.dispose();
    planeMat.dispose();
    if (loadedTexture && loadedTexture.dispose) loadedTexture.dispose();

    // Dispose any child geometry/material (e.g., text)
    root.traverse((obj) => {
      if (obj.geometry && obj.geometry.dispose) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m && m.dispose && m.dispose());
        } else {
          obj.material.dispose && obj.material.dispose();
        }
      }
    });

    // Kill stored primitive cleanups
    primitiveCleanups.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        // ignore
      }
    });

    // Kill any GSAP timelines stored on userData
    if (Array.isArray(root.userData._gsapTimelines)) {
      root.userData._gsapTimelines.forEach((tl) => tl.kill && tl.kill());
    }
  };

  return root;
}
